package parser

import (
	"reflect"
	"strings"
	"testing"
)

var line = "id,name,email,price,qty,sku,created_at,updated_at"
var sink []string

func TestSame(t *testing.T) {
	for _, s := range []string{"", ",", "a", "a,", ",a", "a,,b", line} {
		if !reflect.DeepEqual(Fields(s), strings.Split(s, ",")) {
			t.Fatalf("mismatch %q", s)
		}
	}
}
func BenchmarkFields(b *testing.B) {
	for i := 0; i < b.N; i++ { sink = Fields(line) }
}
func BenchmarkSplit(b *testing.B) {
	for i := 0; i < b.N; i++ { sink = strings.Split(line, ",") }
}
EOF
cd benchcheck && go version && go test ./parser -run Same -bench . -benchmem -count=5 2>&1 | tail -20

